import React, { useState, useEffect } from "react";
import axios from "axios";

function AdminDashboard() {
  const [menuItems, setMenuItems] = useState([]);
  const [newItem, setNewItem] = useState({ name: "", category: "", price: "", available: 1 });
  const [summary, setSummary] = useState({});
  const [chefPerformance, setChefPerformance] = useState([]);

  const loadDashboardData = () => {
    axios.get("http://localhost:5000/api/menu")
      .then(res => setMenuItems(res.data))
      .catch(err => console.error("Error fetching menu:", err));

    axios.get("http://localhost:5000/api/dashboard/summary")
      .then(res => setSummary(res.data))
      .catch(err => console.error("Error fetching summary:", err));

    axios.get("http://localhost:5000/api/chefs/performance")
      .then(res => setChefPerformance(res.data))
      .catch(err => console.error("Error fetching chef performance:", err));
  };

  // Load data
  useEffect(() => {
    loadDashboardData();
  }, []);

  // Add new menu item
  const addMenuItem = () => {
    if (!newItem.name || !newItem.category || !newItem.price) {
      alert("All fields are required");
      return;
    }
    axios.post("http://localhost:5000/api/menu", newItem)
      .then(res => {
        alert("Menu item added!");
        setNewItem({ name: "", category: "", price: "", available: 1 });
        axios.get("http://localhost:5000/api/menu")
          .then(r => setMenuItems(r.data));
      })
      .catch(err => alert("Error adding item: " + err.message));
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Admin Dashboard</h2>

      {/* Business Summary */}
      <section style={{ marginBottom: "30px" }}>
        <h3>Business Summary</h3>
        <p>Total Orders: {summary.totalOrders}</p>
        <p>Total Revenue: ₹{summary.revenue}</p>
        <p>Active Tables: {summary.activeTables}</p>
      </section>

      {/* Menu Management */}
      <section style={{ marginBottom: "30px" }}>
        <h3>Manage Menu</h3>
        <div style={{ display: "flex", gap: "10px", marginBottom: "10px" }}>
          <input
            type="text"
            placeholder="Name"
            value={newItem.name}
            onChange={e => setNewItem({ ...newItem, name: e.target.value })}
          />
          <input
            type="text"
            placeholder="Category"
            value={newItem.category}
            onChange={e => setNewItem({ ...newItem, category: e.target.value })}
          />
          <input
            type="number"
            placeholder="Price"
            value={newItem.price}
            onChange={e => setNewItem({ ...newItem, price: e.target.value })}
          />
          <select
            value={newItem.available}
            onChange={e => setNewItem({ ...newItem, available: parseInt(e.target.value) })}
          >
            <option value={1}>Available</option>
            <option value={0}>Unavailable</option>
          </select>
          <button onClick={addMenuItem}>Add Item</button>
        </div>

        <ul>
          {menuItems.map(item => (
            <li key={item.id}>
              {item.name} — {item.category} — ₹{item.price} — {item.available ? "Available" : "Unavailable"}
            </li>
          ))}
        </ul>
      </section>

      {/* Chef Performance */}
      <section>
        <h3>Chef Performance</h3>
        {chefPerformance.length === 0 ? (
          <p>No chef data yet.</p>
        ) : (
          <ul>
            {chefPerformance.map(c => (
              <li key={c.chef_id}>
                Chef {c.chef_id} — Orders Handled: {c.ordersHandled}
              </li>
            ))}
          </ul>
        )}
      </section>
    </div>
  );
}

export default AdminDashboard;
